function normalizePublicHealthLaunchCommandBriefAction(brief, payload = {}, user = {}) {
  const now = new Date().toISOString();
  const action = String(payload.action || "record-launch-command-brief").trim();
  const receiptAction = ["acknowledge-launch-command-brief", "escalate-launch-command-brief-receipt"].includes(action);
  const status = String(payload.status || (receiptAction ? brief.status || "published" : "published")).trim().toLowerCase();
  if (!new Set(["draft-ready", "published", "sent", "held", "escalated", "blocked", "archived", "closed"]).has(status)) {
    throw new Error("status must be draft-ready, published, sent, held, escalated, blocked, archived or closed");
  }
  const note = String(payload.note || payload.comment || "").trim();
  const audience = normalizeStringList(brief.audience);
  const acknowledgements = Array.isArray(brief.acknowledgements) ? brief.acknowledgements.filter((item) => item && typeof item === "object").slice(0, 48) : [];
  let acknowledgementTarget = "";
  let acknowledgementStatus = "";
  let updatedAcknowledgements = acknowledgements;
  if (receiptAction) {
    const alreadyPublished = /published|sent|approved|archived|complete|closed/i.test(`${brief.status || ""} ${brief.decision || ""} ${brief.publishStatus || ""}`);
    if (!alreadyPublished) throw new Error("launch command brief must be published before recording a delivery receipt");
    acknowledgementTarget = String(payload.acknowledgementTarget || payload.recipient || payload.audience || "").trim();
    if (!acknowledgementTarget) throw new Error("acknowledgementTarget is required for launch command brief delivery receipts");
    if (!audience.includes(acknowledgementTarget)) throw new Error("acknowledgementTarget must be one of the configured brief audiences");
    if (!note) throw new Error("note is required for launch command brief delivery receipts");
    acknowledgementStatus = action === "acknowledge-launch-command-brief" ? "acknowledged" : "escalated";
    const acknowledgement = {
      id: randomUUID(),
      at: now,
      target: acknowledgementTarget,
      status: acknowledgementStatus,
      actor: user.name || user.username || "public health operator",
      role: user.role || "commission",
      note
    };
    updatedAcknowledgements = [acknowledgement, ...acknowledgements.filter((item) => String(item.target || "") !== acknowledgementTarget)].slice(0, 48);
  }
  const history = {
    id: randomUUID(),
    at: now,
    action,
    status,
    actor: user.name || user.username || "public health operator",
    role: user.role || "commission",
    publishStatus: String(payload.publishStatus || status).trim(),
    decision: String(payload.decision || (status === "published" ? "broadcast" : status)).trim(),
    decisionOwner: String(payload.decisionOwner || brief.decisionOwner || "").trim(),
    publishChannel: String(payload.publishChannel || brief.publishChannel || "").trim(),
    artifactName: String(payload.artifactName || payload.artifact || brief.name || "public health launch command brief").trim(),
    attachmentNames: normalizeStringList(payload.attachmentNames || payload.attachments).slice(0, 16),
    acknowledgementTarget,
    acknowledgementStatus,
    note: note || "Public health launch command brief recorded."
  };
  return {
    history,
    brief: {
      ...brief,
      status,
      publishStatus: history.publishStatus,
      decision: history.decision,
      decisionOwner: history.decisionOwner || brief.decisionOwner || "",
      publishChannel: history.publishChannel || brief.publishChannel || "",
      publishedBy: ["published", "sent", "archived", "closed"].includes(status) ? (user.name || user.username || brief.publishedBy || "") : (brief.publishedBy || ""),
      publishedAt: ["published", "sent"].includes(status) && !receiptAction ? now : (brief.publishedAt || ""),
      archivedAt: ["archived", "closed"].includes(status) ? now : (brief.archivedAt || ""),
      acknowledgements: updatedAcknowledgements,
      lastAction: history,
      actionHistory: [history, ...(Array.isArray(brief.actionHistory) ? brief.actionHistory : [])].slice(0, 30),
      updatedAt: now,
      updatedBy: user.username || user.role || "commission",
      updatedByName: user.name || "public health operator"
    }
  };
}

function normalizePublicHealthSiteEvidenceVerificationTaskAction(task, payload = {}, data = {}, user = {}) {
  const now = new Date().toISOString();
  const action = String(payload.action || "start-site-evidence-verification").trim();
  const defaultStatus = action === "verify-site-evidence" ? "verified" : "verification-pending";
  const status = String(payload.status || defaultStatus).trim().toLowerCase();
  if (!new Set(["scheduled", "verification-pending", "verified", "rejected", "escalated"]).has(status)) {
    throw new Error("status must be scheduled, verification-pending, verified, rejected or escalated");
  }
  const evidenceId = String(payload.evidenceId || payload.siteEvidenceId || task.evidenceId || "").trim();
  const evidenceRows = Array.isArray(data.siteLaunchEvidence) ? data.siteLaunchEvidence : [];
  const evidence = evidenceRows.find((item) => item.id === evidenceId);
  if (status === "verified") {
    if (!evidenceId) throw new Error("evidenceId is required to verify a site evidence task");
    if (!evidence || String(evidence.status || "").toLowerCase() !== "verified") {
      throw new Error("evidenceId must reference verified site launch evidence");
    }
    if (String(evidence.templateId || "") !== String(task.templateId || "")) {
      throw new Error("evidenceId template does not match this site evidence verification task");
    }
  }
  const history = {
    id: randomUUID(),
    at: now,
    action,
    status,
    evidenceId,
    actor: user.name || user.username || "public health operator",
    role: user.role || "commission",
    artifactName: String(payload.artifactName || payload.artifact || evidence?.artifactName || task.name || "public health site evidence verification").trim(),
    attachmentNames: normalizeStringList(payload.attachmentNames || payload.attachments || evidence?.attachmentNames).slice(0, 16),
    note: String(payload.note || payload.comment || "Public health site evidence verification task recorded.").trim()
  };
  return {
    history,
    task: {
      ...task,
      status,
      evidenceId: status === "verified" ? evidenceId : (evidenceId || task.evidenceId || ""),
      evidenceTemplateId: status === "verified" ? evidence?.templateId || task.templateId : (task.evidenceTemplateId || ""),
      verifiedBy: status === "verified" ? (user.name || user.username || task.verifiedBy || "") : (task.verifiedBy || ""),
      verifiedAt: status === "verified" ? now : (task.verifiedAt || ""),
      rejectedAt: status === "rejected" ? now : (task.rejectedAt || ""),
      escalatedAt: status === "escalated" ? now : (task.escalatedAt || ""),
      lastAction: history,
      actionHistory: [history, ...(Array.isArray(task.actionHistory) ? task.actionHistory : [])].slice(0, 30),
      updatedAt: now,
      updatedBy: user.username || user.role || "commission",
      updatedByName: user.name || "public health operator"
    }
  };
}

function normalizePublicHealthStandardImplementationAction(entry, payload = {}, data = {}, user = {}) {
  const now = new Date().toISOString();
  const action = String(payload.action || "review-standard-mapping").trim();
  const supportedActions = new Set([
    "review-standard-mapping",
    "record-standard-gap",
    "escalate-standard-gap",
    "assign-standard-gap-remediation",
    "link-standard-site-evidence",
    "verify-standard-gap-remediation"
  ]);
  if (!supportedActions.has(action)) {
    throw new Error("unsupported public health standard implementation action");
  }
  const defaultStatus = action === "record-standard-gap"
    ? "gap-recorded"
    : action === "escalate-standard-gap"
      ? "escalated"
      : action === "assign-standard-gap-remediation"
        ? (String(entry.status || "").toLowerCase() === "escalated" ? "escalated" : "gap-recorded")
        : ["link-standard-site-evidence", "verify-standard-gap-remediation"].includes(action)
          ? "evidence-linked"
          : "reviewed";
  const status = String(payload.status || defaultStatus).trim().toLowerCase();
  if (!new Set(["modeled", "reviewed", "gap-recorded", "escalated", "evidence-linked"]).has(status)) {
    throw new Error("status must be modeled, reviewed, gap-recorded, escalated or evidence-linked");
  }
  const note = String(payload.note || payload.comment || "").trim();
  if (["record-standard-gap", "escalate-standard-gap", "assign-standard-gap-remediation", "verify-standard-gap-remediation"].includes(action) && !note) {
    throw new Error("note is required when recording, escalating, assigning or verifying a standard implementation gap");
  }
  const existingGapStatus = String(entry.gapStatus || "").toLowerCase();
  const hasRecordedGap = ["gap-recorded", "escalated"].includes(String(entry.status || "").toLowerCase()) || /open|gap|blocked|escalated|assigned|in-progress|evidence-submitted/.test(existingGapStatus);
  const remediationOwner = String(payload.remediationOwner || entry.remediationOwner || "").trim();
  const remediationDueAt = String(payload.remediationDueAt || entry.remediationDueAt || "").trim();
  if (action === "assign-standard-gap-remediation") {
    if (!hasRecordedGap) throw new Error("a recorded standard implementation gap is required before remediation can be assigned");
    if (!remediationOwner || !/^\d{4}-\d{2}-\d{2}$/.test(remediationDueAt)) {
      throw new Error("remediationOwner and remediationDueAt (YYYY-MM-DD) are required when assigning a standard implementation gap");
    }
  }
  if (action === "verify-standard-gap-remediation" && !hasRecordedGap) {
    throw new Error("a recorded standard implementation gap is required before remediation can be verified");
  }
  const siteEvidenceId = String(payload.siteEvidenceId || payload.evidenceId || entry.siteEvidenceId || "").trim();
  const evidenceRows = Array.isArray(data.siteLaunchEvidence) ? data.siteLaunchEvidence : [];
  const evidence = evidenceRows.find((item) => item.id === siteEvidenceId);
  if (["link-standard-site-evidence", "verify-standard-gap-remediation"].includes(action) && (!siteEvidenceId || !evidence || String(evidence.status || "").toLowerCase() !== "verified")) {
    throw new Error("siteEvidenceId must reference verified site launch evidence before linking it to a standard implementation entry");
  }
  const gapStatus = action === "verify-standard-gap-remediation"
    ? "verified"
    : action === "assign-standard-gap-remediation"
      ? "assigned"
      : status === "gap-recorded" || status === "escalated"
    ? String(payload.gapStatus || (status === "escalated" ? "escalated" : "open")).trim()
    : String(payload.gapStatus || entry.gapStatus || "not-assessed").trim();
  const remediationStatus = action === "verify-standard-gap-remediation"
    ? "verified"
    : action === "assign-standard-gap-remediation"
      ? "assigned"
      : String(entry.remediationStatus || "not-planned").trim();
  const history = {
    id: randomUUID(),
    at: now,
    action,
    status,
    siteEvidenceId,
    gapStatus,
    remediationOwner,
    remediationDueAt,
    remediationStatus,
    actor: user.name || user.username || "public health operator",
    role: user.role || "commission",
    artifactName: String(payload.artifactName || payload.artifact || evidence?.artifactName || entry.name || "public health standard implementation mapping").trim(),
    attachmentNames: normalizeStringList(payload.attachmentNames || payload.attachments || evidence?.attachmentNames).slice(0, 16),
    note: note || "Public health standard implementation mapping recorded."
  };
  return {
    history,
    entry: {
      ...entry,
      status,
      gapStatus,
      siteEvidenceId: ["link-standard-site-evidence", "verify-standard-gap-remediation"].includes(action) ? siteEvidenceId : (siteEvidenceId || entry.siteEvidenceId || ""),
      reviewedBy: status === "reviewed" ? (user.name || user.username || entry.reviewedBy || "") : (entry.reviewedBy || ""),
      reviewedAt: status === "reviewed" ? now : (entry.reviewedAt || ""),
      gapRecordedAt: status === "gap-recorded" ? now : (entry.gapRecordedAt || ""),
      escalatedAt: status === "escalated" ? now : (entry.escalatedAt || ""),
      remediationOwner,
      remediationDueAt,
      remediationStatus,
      remediationAssignedAt: action === "assign-standard-gap-remediation" ? now : (entry.remediationAssignedAt || ""),
      remediationVerifiedAt: action === "verify-standard-gap-remediation" ? now : (entry.remediationVerifiedAt || ""),
      lastAction: history,
      actionHistory: [history, ...(Array.isArray(entry.actionHistory) ? entry.actionHistory : [])].slice(0, 30),
      updatedAt: now,
      updatedBy: user.username || user.role || "commission",
      updatedByName: user.name || "public health operator"
    }
  };
}

function normalizePublicHealthLaunchGateAction(approval, payload = {}, user = {}, approvalPreflight = {}) {
  const now = new Date().toISOString();
  const status = String(payload.status || payload.decision || "submitted").trim().toLowerCase();
  if (!new Set(["submitted", "approved", "rejected", "revoked"]).has(status)) {
    throw new Error("status must be submitted, approved, rejected or revoked");
  }
  if (status === "approved" && !approvalPreflight.eligible) {
    throw new Error("launch approval is blocked until all prerequisite launch requirements pass");
  }
  if (status === "approved" && String(payload.confirmation || "").trim() !== "APPROVE PUBLIC HEALTH LAUNCH") {
    throw new Error("confirmation must be APPROVE PUBLIC HEALTH LAUNCH");
  }
  const history = {
    id: randomUUID(),
    at: now,
    action: String(payload.action || "submit-launch-approval").trim(),
    status,
    actor: user.name || user.username || "public health operator",
    role: user.role || "commission",
    note: String(payload.note || payload.comment || "Public health launch gate approval recorded.").trim(),
    artifactName: String(payload.artifactName || payload.artifact || "public health launch approval").trim(),
    attachmentNames: normalizeStringList(payload.attachmentNames || payload.attachments).slice(0, 12),
    preflightStatus: approvalPreflight.status || "unknown",
    blockedRequirementIds: Array.isArray(approvalPreflight.blockedRequirementIds) ? approvalPreflight.blockedRequirementIds : []
  };
  return {
    history,
    approval: {
      ...approval,
      status,
      decision: status,
      signedBy: status === "approved" ? (user.name || user.username || approval.signedBy || "") : (approval.signedBy || ""),
      signedAt: status === "approved" ? now : (approval.signedAt || ""),
      lastAction: history,
      actionHistory: [history, ...(Array.isArray(approval.actionHistory) ? approval.actionHistory : [])].slice(0, 20),
      updatedAt: now,
      updatedBy: user.username || user.role || "commission",
      updatedByName: user.name || "public health operator"
    }
  };
}

function normalizeHealthStatisticsImportJob(payload, user) {
  return {
    id: payload.id || `stat-job-${randomUUID()}`,
    name: String(payload.name || "未命名统计导入任务").trim(),
    source: String(payload.source || "报表导入").trim(),
    period: String(payload.period || "未指定周期").trim(),
    status: String(payload.status || "待解析").trim(),
    quality: String(payload.quality || "待质控").trim(),
    target: String(payload.target || "healthStatistics").trim(),
    nextAction: String(payload.nextAction || "完成字段映射和人工复核。").trim(),
    createdAt: new Date().toISOString(),
    createdBy: user?.username || user?.name || "system"
  };
}

function cleanWorkflowUpdates(updates) {
  return Object.entries(updates && typeof updates === "object" ? updates : {}).reduce((result, [key, value]) => {
    if (WORKFLOW_PROTECTED_FIELDS.has(key)) return result;
    if (["string", "number", "boolean"].includes(typeof value) || value === null) {
      result[key] = value;
    }
    return result;
  }, {});
}

function appendDrugConsumableAuditTrail(item, user, action, detail) {
  if (!item || typeof item !== "object") return;
  item.auditTrail = [
    {
      at: new Date().toISOString(),
      actor: user?.username || user?.role || "system",
      role: user?.role || "system",
      action,
      result: item.status || item.reviewStatus || item.remediationStatus || "updated",
      detail: String(detail || item.nextAction || "").trim()
    },
    ...(Array.isArray(item.auditTrail) ? item.auditTrail : [])
  ].slice(0, 20);
}

function cleanResidentPatch(patch) {
  return Object.entries(patch && typeof patch === "object" ? patch : {}).reduce((result, [key, value]) => {
    if (RESIDENT_PROTECTED_FIELDS.has(key) || key === "expectedVersion") return result;
    if (["string", "number", "boolean"].includes(typeof value) || value === null || Array.isArray(value) || (value && typeof value === "object")) {
      result[key] = value;
    }
    return result;
  }, {});
}

function cleanBusinessPatch(patch) {
  return Object.entries(patch && typeof patch === "object" ? patch : {}).reduce((result, [key, value]) => {
    if (WORKFLOW_PROTECTED_FIELDS.has(key) || key === "expectedVersion") return result;
    if (["string", "number", "boolean"].includes(typeof value) || value === null || Array.isArray(value) || (value && typeof value === "object")) {
      result[key] = value;
    }
    return result;
  }, {});
}

function cleanMultiPracticePatch(patch) {
  return Object.entries(patch && typeof patch === "object" ? patch : {}).reduce((result, [key, value]) => {
    if (MULTI_PRACTICE_PROTECTED_FIELDS.has(key)) return result;
    if (["string", "number", "boolean"].includes(typeof value) || value === null || Array.isArray(value) || (value && typeof value === "object")) {
      result[key] = value;
    }
    return result;
  }, {});
}

function normalizeMultiPracticeScheduleText(value) {
  return String(value || "")
    .replace(/\s+/g, "")
    .replace(/[，,；;]/g, "|")
    .trim()
    .toLowerCase();
}

function isActiveMultiPracticeStatus(status) {
  const text = String(status || "");
  return !["已撤回", "已终止", "备案终止", "终止", "withdrawn", "terminated"].some((item) => text.includes(item));
}

function detectMultiPracticeScheduleConflicts(application = {}, applications = []) {
  const schedule = normalizeMultiPracticeScheduleText(application.schedule);
  if (!application.doctorId || !schedule) return [];
  return (applications || [])
    .filter((item) =>
      item &&
      item.id !== application.id &&
      item.doctorId === application.doctorId &&
      isActiveMultiPracticeStatus(item.status) &&
      normalizeMultiPracticeScheduleText(item.schedule) === schedule
    )
    .map((item) => ({
      id: item.id,
      targetInstitution: item.targetInstitution || "",
      targetDepartment: item.targetDepartment || "",
      schedule: item.schedule || "",
      status: item.status || ""
    }))
    .slice(0, 10);
}

function buildMultiPracticeExternalSync(application = {}, profile = {}, action = "sync", user = {}) {
  const electronic = application.electronicRegistrationVerification || verifyDoctorElectronicRegistration(profile);
  const confirmation = application.primaryPracticeConfirmation && typeof application.primaryPracticeConfirmation === "object"
    ? application.primaryPracticeConfirmation
    : {};
  return {
    action,
    syncedAt: new Date().toISOString(),
    electronicRegistration: {
      status: electronic.verificationStatus || "pending",
      registryId: electronic.registryId || profile.electronicRegistration?.registryId || "",
      licenseNo: profile.licenseNo || "",
      signatureNo: electronic.signatureNo || profile.electronicRegistration?.signatureNo || ""
    },
    eSignature: {
      status: confirmation.signatureNo ? "signed" : "pending",
      signatureNo: confirmation.signatureNo || "",
      signerOrg: confirmation.confirmedByOrg || application.primaryInstitution || profile.primaryInstitution || ""
    },
    hisHr: {
      status: profile.primaryInstitutionId || application.primaryInstitutionId ? "mapped" : "pending",
      employeeId: profile.hrEmployeeId || profile.id || application.doctorId || "",
      primaryInstitutionId: application.primaryInstitutionId || profile.primaryInstitutionId || "",
      operator: user.username || user.name || "system"
    }
  };
}

function resolveMultiPracticeLifecyclePatch(payload = {}) {
  const action = String(payload.action || payload.lifecycleAction || "").trim();
  const statusByAction = {
    "return-correction": "退回补正",
    "suspend": "暂停执业",
    "withdraw": "已撤回",
    "terminate": "已终止",
    "approve-filing": "已备案",
    "file": "已备案",
    "confirm": "待卫健审核"
  };
  const status = payload.status || statusByAction[action] || "";
  const publicVisible = ["withdraw", "terminate"].includes(action) ? false : payload.publicVisible;
  return {
    action,
    status,
    ...(publicVisible !== undefined ? { publicVisible } : {}),
    correctionRequired: action === "return-correction"
      ? String(payload.correctionRequired || payload.note || "请补齐多点执业协议、责任保险或第一执业地点意见").trim()
      : payload.correctionRequired
  };
}

function refreshMultiPracticeReviewState(application, profile, applications = [], action = "sync", user = {}) {
  const scheduleConflictEvidence = detectMultiPracticeScheduleConflicts(application, applications);
  const reviewed = {
    ...application,
    scheduleConflictEvidence,
    scheduleConflict: Boolean(application.scheduleConflict) || scheduleConflictEvidence.length > 0
  };
  reviewed.externalSync = buildMultiPracticeExternalSync(reviewed, profile || {}, action, user);
  return withMultiPracticeReviewState(reviewed, profile);
}

function syncMultiPracticeDocumentChecks(application) {
  const previous = application.documentChecks && typeof application.documentChecks === "object" ? application.documentChecks : {};
  return {
    ...previous,
    firstPracticeConsent: primaryPracticeConfirmed(application),
    cooperationAgreement: Boolean(String(application.responsibility || "").trim() && String(application.compensation || "").trim()),
    liabilityInsurance: Boolean(String(application.insurance || "").trim()),
    scheduleConflict: Boolean(application.scheduleConflict) || (Array.isArray(application.scheduleConflictEvidence) && application.scheduleConflictEvidence.length > 0),
    publicDisclosure: application.publicVisible !== false
  };
}

function hasMultiPracticeRisk(application) {
  const compliance = application.compliance || {};
  const documents = syncMultiPracticeDocumentChecks(application);
  const complianceBlocked = Object.entries(compliance)
    .some(([key, value]) => key !== "publicHospitalLeaderRestricted" && !value);
  return Boolean(
    compliance.publicHospitalLeaderRestricted ||
    complianceBlocked ||
    documents.scheduleConflict ||
    documents.firstPracticeConsent === false ||
    documents.cooperationAgreement === false ||
    documents.liabilityInsurance === false ||
    String(application.status || "").includes("退回") ||
    String(application.status || "").includes("补正")
  );
}

function multiPracticeRiskFlags(application) {
  const compliance = application.compliance || {};
  const documents = syncMultiPracticeDocumentChecks(application);
  return [
    compliance.publicHospitalLeaderRestricted ? "public-hospital-leader-restricted" : "",
    compliance.electronicRegistrationVerified === false ? "electronic-registration-unverified" : "",
    compliance.registrationInForce === false ? "registration-expired" : "",
    compliance.titleQualified === false ? "title-not-qualified" : "",
    compliance.fiveYears === false ? "years-not-qualified" : "",
    compliance.assessmentQualified === false ? "assessment-not-qualified" : "",
    compliance.scopeMatched === false ? "scope-not-matched" : "",
    compliance.agreementCompleted === false ? "agreement-incomplete" : "",
    documents.firstPracticeConsent === false ? "first-practice-consent-missing" : "",
    documents.cooperationAgreement === false ? "cooperation-agreement-missing" : "",
    documents.liabilityInsurance === false ? "liability-insurance-missing" : "",
    documents.scheduleConflict ? "schedule-conflict" : "",
    String(application.status || "").includes("退回") ? "returned" : "",
    String(application.status || "").includes("补正") ? "correction-required" : ""
  ].filter(Boolean);
}

function withMultiPracticeReviewState(application, profile = null) {
  const electronicRegistrationVerification = application.electronicRegistrationVerification || (profile ? verifyDoctorElectronicRegistration(profile) : undefined);
  const compliance = profile ? qualificationCompliance(profile, application) : (application.compliance || {});
  const reviewed = {
    ...application,
    ...(electronicRegistrationVerification ? { electronicRegistrationVerification } : {}),
    compliance,
    documentChecks: syncMultiPracticeDocumentChecks(application)
  };
  return {
    ...reviewed,
    riskFlags: multiPracticeRiskFlags(reviewed)
  };
}

function buildMultiPracticeRegistry(data, user) {
  const applications = (data.multiPracticeApplications || [])
    .filter((item) => canAccessMultiPracticeApplication(user, item))
    .map((item) => {
      const profile = (data.doctorProfiles || []).find((doctor) => doctor.id === item.doctorId);
      const reviewed = refreshMultiPracticeReviewState(
        item,
        profile,
        (data.multiPracticeApplications || []).filter((application) => application.id !== item.id),
        "registry",
        user
      );
      return {
        id: reviewed.id,
        doctorId: reviewed.doctorId,
        doctorName: reviewed.doctorName,
        title: reviewed.title,
        specialty: reviewed.specialty,
        practiceScope: reviewed.practiceScope,
        electronicRegistrationVerification: reviewed.electronicRegistrationVerification,
        primaryInstitution: reviewed.primaryInstitution,
        targetInstitution: reviewed.targetInstitution,
        targetDepartment: reviewed.targetDepartment,
        period: reviewed.period,
        schedule: reviewed.schedule,
        registrationMode: reviewed.registrationMode || "备案管理",
        primaryConsent: reviewed.primaryConsent,
        primaryPracticeConfirmation: reviewed.primaryPracticeConfirmation,
        status: reviewed.status || "待处理",
        publicVisible: reviewed.publicVisible !== false,
        compliance: reviewed.compliance || {},
        documentChecks: reviewed.documentChecks,
        scheduleConflictEvidence: Array.isArray(reviewed.scheduleConflictEvidence) ? reviewed.scheduleConflictEvidence : [],
        externalSync: reviewed.externalSync || buildMultiPracticeExternalSync(reviewed, profile || {}, "registry", user),
        risk: reviewed.riskFlags.length > 0,
        riskFlags: reviewed.riskFlags,
        disclosureItems: reviewed.disclosureItems || [],
        lifecycle: Array.isArray(reviewed.lifecycle) ? reviewed.lifecycle.slice(0, 5) : [],
        lastUpdated: reviewed.lastUpdated
      };
    });
  const publicLedger = applications.filter((item) => item.publicVisible).map((item) => ({
    id: item.id,
    doctorName: item.doctorName,
    title: item.title,
    specialty: item.specialty,
    practiceScope: item.practiceScope,
    primaryInstitution: item.primaryInstitution,
    targetInstitution: item.targetInstitution,
    targetDepartment: item.targetDepartment,
    period: item.period,
    schedule: item.schedule,
    registrationMode: item.registrationMode,
    status: item.status
  }));
  const reviewQueue = applications
    .filter((item) => item.risk || String(item.status || "").includes("待"))
    .sort((left, right) => Number(right.risk) - Number(left.risk) || String(right.lastUpdated || "").localeCompare(String(left.lastUpdated || "")));
  return {
    ok: true,
    generatedAt: new Date().toISOString(),
    summary: {
      total: applications.length,
      pending: applications.filter((item) => String(item.status || "").includes("待")).length,
      filed: applications.filter((item) => String(item.status || "").includes("备案")).length,
      publicVisible: publicLedger.length,
      risk: applications.filter((item) => item.risk).length,
      firstPracticeConsentMissing: applications.filter((item) => item.documentChecks.firstPracticeConsent === false).length,
      scheduleConflicts: applications.filter((item) => item.documentChecks.scheduleConflict).length
    },
    publicLedger,
    reviewQueue,
    applications,
    policy: data.multiPracticePolicy || seedMultiPracticePolicy()
  };
}

function patchCollectionItem({ data, collection, id, patch, user, action, protectedFields = WORKFLOW_PROTECTED_FIELDS }) {
  const rows = Array.isArray(data[collection]) ? data[collection] : [];
  const index = rows.findIndex((item) => item.id === id);
  if (index < 0) return { status: 404, body: { error: "Not Found", message: "未找到业务记录" } };
  const safePatch = Object.entries(patch && typeof patch === "object" ? patch : {}).reduce((result, [key, value]) => {
    if (protectedFields.has(key) || key === "expectedVersion") return result;
    if (["string", "number", "boolean"].includes(typeof value) || value === null || Array.isArray(value) || (value && typeof value === "object")) {
      result[key] = value;
    }
    return result;
  }, {});
  rows[index] = {
    ...rows[index],
    ...safePatch,
    updatedBy: user.username || user.role,
    updatedByName: user.name,
    lastUpdated: new Date().toISOString()
  };
  data[collection] = rows;
  if (Object.hasOwn(patch, "expectedVersion")) {
    data.storageMeta = {
      ...(data.storageMeta || {}),
      collectionVersions: { [collection]: Number(patch.expectedVersion) }
    };
  }
  data.securityEvents = prependAuditTrailEntry(data.securityEvents, {
    id: randomUUID(),
    at: new Date().toLocaleString("zh-CN", { hour12: false }),
    actor: user.name,
    role: user.role,
    action,
    target: `${collection}/${id}`,
    result: "允许",
    detail: `集合项更新 ${collection}`
  });
  writeDatabase(data);
  return { status: 200, body: rows[index] };
}

function patchBusinessCollectionItem({ data, collection, id, patch, user, action, command, prepareCas, versionConflictCode, idempotencyConflictCode }) {
  const rows = Array.isArray(data[collection]) ? data[collection] : [];
  const index = rows.findIndex((item) => item.id === id);
  if (index < 0) return { status: 404, body: { error: "Not Found", message: "未找到业务记录" } };
  if (!canAccessBusinessRow(user, rows[index], data)) {
    appendSecurityEvent({ actor: user.name, role: user.role, action, target: `${collection}/${id}`, result: "拒绝", detail: "超出居民授权范围" });
    return { status: 403, body: { error: "Forbidden", message: "无权更新该居民业务记录" } };
  }
  if (command) {
    const receipt = (Array.isArray(rows[index]._writeCommandReceipts) ? rows[index]._writeCommandReceipts : [])
      .find((item) => item.commandKeyHash === command.commandKeyHash);
    if (receipt) {
      if (receipt.requestDigest !== command.requestDigest) {
        return { status: 409, body: { error: "Conflict", code: idempotencyConflictCode, collection, message: "idempotency key was already used for another update" } };
      }
      return { status: 200, body: structuredClone(receipt.response), replayed: true };
    }
    prepareCas(data, [collection, "securityEvents"], collection, patch.expectedVersion, versionConflictCode);
  }
  rows[index] = {
    ...rows[index],
    ...cleanBusinessPatch(patch),
    updatedBy: user.username || user.role,
    updatedByName: user.name,
    lastUpdated: new Date().toISOString()
  };
  data[collection] = rows;
  if (!command && Object.hasOwn(patch, "expectedVersion")) {
    data.storageMeta = {
      ...(data.storageMeta || {}),
      collectionVersions: { [collection]: Number(patch.expectedVersion) }
    };
  }
  data.securityEvents = prependAuditTrailEntry(data.securityEvents, {
    id: randomUUID(),
    at: new Date().toLocaleString("zh-CN", { hour12: false }),
    actor: user.name,
    role: user.role,
    action,
    target: `${collection}/${id}`,
    result: "允许",
    detail: `业务级更新 ${collection}`
  });
  if (command) {
    const response = structuredClone(rows[index]);
    delete response._writeCommandReceipts;
    rows[index]._writeCommandReceipts = [
      {
        commandKeyHash: command.commandKeyHash,
        requestDigest: command.requestDigest,
        response,
        recordedAt: rows[index].lastUpdated
      },
      ...(Array.isArray(rows[index]._writeCommandReceipts) ? rows[index]._writeCommandReceipts : [])
    ].slice(0, 20);
  }
  try {
    writeDatabase(data);
  } catch (error) {
    error.stateCommandPersistenceFailure = true;
    throw error;
  }
  const body = structuredClone(rows[index]);
  delete body._writeCommandReceipts;
  return { status: 200, body, replayed: false };
}

function findWorkflowCollection(data, collection) {
  if (collection === "referrals") {
    data.referralSystem = data.referralSystem || seedReferralSystem();
    data.referralSystem.referrals = Array.isArray(data.referralSystem.referrals) ? data.referralSystem.referrals : [];
    return data.referralSystem.referrals;
  }
  if (collection === "multiPracticeApplications") {
    data.multiPracticeApplications = Array.isArray(data.multiPracticeApplications) ? data.multiPracticeApplications : seedMultiPracticeApplications();
    return data.multiPracticeApplications;
  }
  return Array.isArray(data[collection]) ? data[collection] : null;
}

function workflowStateCollectionKey(collection) {
  if (collection === "referrals") return "referralSystem";
  return collection;
}

