function assertPublicHealthRespiratoryPayload(payload = {}, mode = "") {
  const allowedByMode = {
    intake: new Set([
      "expectedVersion", "externalBatchId", "institutionId", "regionCode", "observedAt",
      "ageGroup", "placeType", "specimenCount", "results", "evidenceRefs",
      "idempotencyKey", "receivedAt", "sourceId", "panelId", "panelVersion"
    ]),
    verify: new Set([
      "action", "expectedVersion", "decision", "note", "evidenceRefs", "idempotencyKey", "at"
    ]),
    publish: new Set([
      "action", "expectedVersion", "note", "evidenceRefs", "idempotencyKey", "at"
    ])
  };
  const allowed = allowedByMode[mode];
  const inspect = (value) => {
    if (Array.isArray(value)) {
      value.forEach(inspect);
      return;
    }
    if (!value || typeof value !== "object") return;
    Object.entries(value).forEach(([key, item]) => {
      const normalized = key.toLowerCase();
      if (PUBLIC_HEALTH_RESPIRATORY_DIRECT_IDENTIFIER_FIELDS.has(normalized)
        || ["id", "version", "status", "sourcerecordhash", "idempotencykeyhash",
          "contentfingerprint", "verification", "publication", "integritydigest",
          "positivityrate", "signalids"].includes(normalized)) {
        const error = new Error("public health respiratory pathogen client override is forbidden");
        error.code = "PUBLIC_HEALTH_RESPIRATORY_PATHOGEN_PAYLOAD_FORBIDDEN";
        throw error;
      }
      inspect(item);
    });
  };
  const unexpected = Object.keys(payload).find((key) => !allowed?.has(key));
  if (unexpected) {
    const error = new Error("public health respiratory pathogen client override is forbidden");
    error.code = "PUBLIC_HEALTH_RESPIRATORY_PATHOGEN_PAYLOAD_FORBIDDEN";
    throw error;
  }
  (payload.results || []).forEach((result) => {
    const unexpectedResult = Object.keys(result || {})
      .find((key) => !["pathogenCode", "testedSpecimens", "positiveSpecimens"].includes(key));
    if (unexpectedResult) {
      const error = new Error("public health respiratory pathogen result override is forbidden");
      error.code = "PUBLIC_HEALTH_RESPIRATORY_PATHOGEN_PAYLOAD_FORBIDDEN";
      throw error;
    }
  });
  inspect(payload);
}

function publicHealthRespiratoryPathogenActor(user = {}, purpose = "verify") {
  const actorId = String(user.username || user.id || "").trim();
  if (!actorId) {
    const error = new Error("public health respiratory pathogen actor identity is required");
    error.code = "PUBLIC_HEALTH_MODERNIZATION_FORBIDDEN";
    throw error;
  }
  return {
    id: actorId,
    username: actorId,
    name: actorId,
    role: purpose === "intake" && user.role === "institution"
      ? "laboratory"
      : purpose === "intake"
        ? "cdc-surveillance"
        : "commission"
  };
}

function publicHealthSurveillanceModelActor(user = {}, purpose = "run") {
  const actorId = String(user.username || user.id || "").trim();
  if (!actorId) {
    const error = new Error("public health surveillance model actor identity is required");
    error.code = "PUBLIC_HEALTH_MODERNIZATION_FORBIDDEN";
    throw error;
  }
  if (purpose === "submit-validation"
    && String(user.orgType || "").trim() !== "health_admin") {
    const error = new Error("only the designated public health owner may submit model validation");
    error.code = "PUBLIC_HEALTH_MODERNIZATION_FORBIDDEN";
    throw error;
  }
  return {
    id: actorId,
    username: actorId,
    name: actorId,
    role: purpose === "submit-validation" ? "cdc-surveillance" : "commission"
  };
}

function publicHealthModernizationSafeCode(error) {
  const explicit = String(error?.code || "").trim();
  if (/^PUBLIC_HEALTH_(?:MODERNIZATION|SURVEILLANCE_(?:RULE|MODEL)|RESPIRATORY_(?:PATHOGEN|NETWORK))_[A-Z0-9_]+$/.test(explicit)) return explicit;
  const message = String(error?.message || "");
  if (/unknown public health surveillance signal|unknown public health surveillance alert|unknown medical-prevention task|unknown public health rule change|unknown public health surveillance model|unknown public health model validation|unknown public health respiratory pathogen batch/i.test(message)) {
    return "PUBLIC_HEALTH_MODERNIZATION_RECORD_NOT_FOUND";
  }
  if (/role .*not allowed/i.test(message)) return "PUBLIC_HEALTH_MODERNIZATION_FORBIDDEN";
  if (/activation (?:verification secret|signing keyring) is required|activation verification secret must contain|rule activation keyring purpose/i.test(message)) {
    return "PUBLIC_HEALTH_SURVEILLANCE_RULE_ACTIVATION_KEYRING_UNAVAILABLE";
  }
  if (/reviewer must be independent/i.test(message)) {
    return "PUBLIC_HEALTH_SURVEILLANCE_RULE_REVIEWER_NOT_INDEPENDENT";
  }
  if (/model validation requires an independent reviewer/i.test(message)) {
    return "PUBLIC_HEALTH_SURVEILLANCE_MODEL_REVIEWER_NOT_INDEPENDENT";
  }
  if (/model run integrity invalid|model validation integrity invalid|ungoverned-model-materialization/i.test(message)) {
    return "PUBLIC_HEALTH_SURVEILLANCE_MODEL_INTEGRITY_INVALID";
  }
  if (/respiratory pathogen batch integrity invalid|respiratory pathogen publication idempotency or signal binding conflict/i.test(message)) {
    return "PUBLIC_HEALTH_RESPIRATORY_PATHOGEN_INTEGRITY_INVALID";
  }
  if (/respiratory network evidence.*(?:signature|integrity|audit|untrusted)|receipt signature mismatch/i.test(message)) {
    return "PUBLIC_HEALTH_RESPIRATORY_NETWORK_EVIDENCE_INTEGRITY_INVALID";
  }
  if (/rule registry integrity invalid|rule change integrity invalid|trusted public health rule activation failed/i.test(message)) {
    return "PUBLIC_HEALTH_SURVEILLANCE_RULE_INTEGRITY_INVALID";
  }
  if (/version conflict|CAS conflict/i.test(message)) return "PUBLIC_HEALTH_MODERNIZATION_VERSION_CONFLICT";
  if (/idempotency|conflict detected|unique conflict/i.test(message)) return "PUBLIC_HEALTH_MODERNIZATION_CONFLICT";
  if (/integrity invalid|integrity is invalid|audit is missing/i.test(message)) {
    return "PUBLIC_HEALTH_MODERNIZATION_INTEGRITY_INVALID";
  }
  if (/not allowed from|only a human-verified|cannot be closed/i.test(message)) {
    return "PUBLIC_HEALTH_MODERNIZATION_STATE_CONFLICT";
  }
  return "PUBLIC_HEALTH_MODERNIZATION_COMMAND_INVALID";
}

function publicHealthModernizationHttpStatus(code) {
  if (code === "PUBLIC_HEALTH_MODERNIZATION_RECORD_NOT_FOUND") return 404;
  if (code === "PUBLIC_HEALTH_MODERNIZATION_FORBIDDEN") return 403;
  if ([
    "PUBLIC_HEALTH_SURVEILLANCE_RULE_ACTIVATION_SECRET_UNAVAILABLE",
    "PUBLIC_HEALTH_SURVEILLANCE_RULE_ACTIVATION_KEYRING_UNAVAILABLE",
    "PUBLIC_HEALTH_SURVEILLANCE_RULE_ACTIVATION_KEYRING_INVALID",
    "PUBLIC_HEALTH_RESPIRATORY_NETWORK_EVIDENCE_KEYRING_UNAVAILABLE",
    "PUBLIC_HEALTH_RESPIRATORY_NETWORK_EVIDENCE_KEYRING_INVALID"
  ].includes(code)) return 503;
  if (/CONFLICT|INTEGRITY_INVALID/.test(code)) return 409;
  return 400;
}

function publicHealthModernizationError(res, error) {
  const code = publicHealthModernizationSafeCode(error);
  sendJson(res, publicHealthModernizationHttpStatus(code), {
    ok: false,
    error: "Public health modernization command rejected",
    code,
    productionReady: false
  });
}

