const regionalRuntime = loadRegionalRuntime({ root: __dirname, env: process.env });
const platformRuntimeComposition = createPlatformRuntimeComposition({
  source: createRuntimeCapabilitySource(),
  regionalRuntime
});
const platformRuntimeContexts = platformRuntimeComposition.contexts;

async function handleApi(req, res) {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const handled = await platformRuntimeComposition.apiRouter.handle(req, res, url);
  if (!handled) sendJson(res, 404, { error: "API not found" });
}

function handleRequestError(_req, res, error) {
    if (isStorageConflict(error)) {
      sendStorageConflict(res, error);
      return;
    }
    if (["SESSION_STORE_UNAVAILABLE", "AUTH_SECURITY_STATE_UNAVAILABLE"].includes(error?.code)) {
      sendJson(res, 503, { ok: false, code: error.code, message: error.message });
      return;
    }
    const failure = publicRequestError(error);
    sendJson(res, failure.status, failure.body);
}

const authorizationHttpRuntime = createAuthorizationHttpRuntime({
  verifySignedSessionToken,
  sessionStore: runtimeSessionStore,
  appendSecurityEvent,
  securityResponseHeaders,
  environment: process.env
});

const staticContentRuntime = createStaticContentRuntime({
  root: ROOT,
  databaseFile: DB_FILE,
  authorization: authorizationHttpRuntime,
  securityResponseHeaders,
  mimeTypes
});

const server = http.createServer(createPlatformRequestHandler({
  observability: platformObservability,
  hydrateRequestSession,
  handleApi,
  serveStatic: staticContentRuntime.serveStatic,
  isProtectedStaticRequest: staticContentRuntime.isProtectedStaticRequest,
  hydrateStaticRequestSession: hydrateRequestSession,
  recordRequestMetrics,
  sendJson,
  handleError: handleRequestError
}));

function startServer(port = PORT) {
  assertProductionRuntimeSecurity();
  if (sessionStoreMode() === "postgres" || authSecurityStateStoreMode() === "postgres") {
    const error = new Error("PostgreSQL authentication state requires asynchronous startup");
    error.code = "POSTGRES_SESSION_ASYNC_START_REQUIRED";
    throw error;
  }
  ensureDatabase();
  runtimeAuthSecurityStateStore();
  cleanupRuntimeSessions({ trigger: "startup", actor: "system" });
  scheduleSessionCleanup();
  return server.listen(port, () => {
    const address = server.address();
    const actualPort = typeof address === "object" && address ? address.port : port;
    console.log(`慢病医防融合管理平台已启动：http://localhost:${actualPort}`);
  });
}

async function startServerAsync(port = PORT) {
  assertProductionRuntimeSecurity();
  ensureDatabase();
  const store = runtimeSessionStore();
  const authStateStore = runtimeAuthSecurityStateStore();
  try {
    if (typeof store.initialize === "function") await store.initialize();
    await authStateStore.status();
    await cleanupRuntimeSessions({ trigger: "startup", actor: "system" });
  } catch (error) {
    if (typeof store.close === "function") {
      try {
        await store.close();
      } catch (closeError) {
        console.error(`session store close after startup failure failed: ${closeError.message}`);
      }
    }
    runtimeSessionStoreInstance = null;
    runtimeSessionStoreKey = "";
    runtimeAuthSecurityStateStoreInstance = null;
    runtimeAuthSecurityStateStoreKey = "";
    if (runtimePostgresPoolInstance) {
      try {
        await runtimePostgresPoolInstance.end();
      } catch (closeError) {
        console.error(`PostgreSQL pool close after startup failure failed: ${closeError.message}`);
      }
      runtimePostgresPoolInstance = null;
    }
    throw error;
  }
  scheduleSessionCleanup();
  return server.listen(port, () => {
    const address = server.address();
    const actualPort = typeof address === "object" && address ? address.port : port;
    console.log(`慢病医防融合管理平台已启动：http://localhost:${actualPort}`);
  });
}

async function stopServer() {
  clearSessionCleanupSchedule();
  if (server.listening) await new Promise((resolve) => server.close(resolve));
  if (digitalHospitalExecutionServiceInstance) {
    digitalHospitalExecutionServiceInstance.close();
    digitalHospitalExecutionServiceInstance = null;
  }
  if (productionAdapterRuntimeInstance) {
    await productionAdapterRuntimeInstance.close();
    productionAdapterRuntimeInstance = null;
  }
  if (runtimeSessionStoreInstance && typeof runtimeSessionStoreInstance.close === "function") {
    await runtimeSessionStoreInstance.close();
  }
  runtimeSessionStoreInstance = null;
  runtimeSessionStoreKey = "";
  runtimeAuthSecurityStateStoreInstance = null;
  runtimeAuthSecurityStateStoreKey = "";
  if (runtimePostgresPoolInstance) await runtimePostgresPoolInstance.end();
  runtimePostgresPoolInstance = null;
}

/* c8 ignore next 8 */
if (require.main === module) {
  startServerAsync().catch((error) => {
    console.error(`server startup failed: ${error.message}`);
    process.exitCode = 1;
  });
  const shutdown = async () => {
    await stopServer();
    process.exit(0);
  };
  process.once("SIGINT", shutdown);
  process.once("SIGTERM", shutdown);
}

